function persist(){if(!save())toast('浏览器存储不足：当前更改仅保留到关闭页面，请及时导出。')}
function render(shouldPersist=true){const graphScroll=[...app.querySelectorAll('[data-graph]')].map(g=>({id:g.dataset.graph,x:g.querySelector('.entity-viewport').scrollLeft,y:g.querySelector('.entity-viewport').scrollTop}));for(const e of state.events){const last=state.sessions.find(s=>s.id===e.batches.at(-1)?.session);if(last)e.execution=last.stage==='Completed'?'已完成':last.stage==='Terminated'?'已终止':last.stage==='Permission'?'待授权':last.state==='RUNNING'?'执行中':last.stage==='Planning'?'待确认计划':last.state}document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('compact',state.preferences.compact);app.innerHTML=renderPage(route);fitEntityGraphs(app);const activeStep=app.querySelector('.case-stepper [aria-current="step"]');if(activeStep){const stepper=activeStep.parentElement;const bounds=stepper.getBoundingClientRect(),active=activeStep.getBoundingClientRect();if(active.right>bounds.right||active.left<bounds.left)stepper.scrollLeft+=active.left-bounds.left-(stepper.clientWidth-activeStep.offsetWidth)/2;}graphScroll.forEach(p=>{const v=app.querySelector(`[data-graph="${p.id}"] .entity-viewport`);if(v){v.scrollLeft=p.x;v.scrollTop=p.y;}});const messages=document.querySelector('#messages');if(messages)messages.scrollTop=current()?.scrollTop||0;document.title=(pages.find(p=>p.id===route)?.name||'研判助手')+' · 交互原型';if(shouldPersist)persist()}
function toast(text){clearTimeout(toastTimer);const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),4200)}
function close(){overlay.innerHTML='';app.inert=false;modalCallback=null;returnFocus?.isConnected&&returnFocus.focus()}
function modal(title,body,opts={}){returnFocus=document.activeElement;app.inert=true;overlay.innerHTML=`<div class="overlay-backdrop ${opts.drawer?'drawer-backdrop':''}"><section class="modal ${opts.wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-header"><h2 id="dialog-title">${esc(title)}</h2>${btn(icon('close'),'close','aria-label="关闭对话框"','ghost icon-only')}</header><div class="modal-body">${body}</div></section></div>`;fitEntityGraphs(overlay);setTimeout(()=>overlay.querySelector('input,textarea,select,button')?.focus(),0)}
function formModal(title,fields,onSubmit,label='确认保存'){modal(title,`<form id="modal-form">${fields}<div class="form-error" role="alert"></div><div class="form-actions">${btn('取消','close')}<button class="btn primary" type="submit">${esc(label)}</button></div></form>`);modalCallback=onSubmit}
function confirm(title,text,callback,label='确认'){formModal(title,note(esc(text),'warning'),()=>{callback();return true},label)}
function commit(message){dirty=false;persist();render();if(message)toast(message)}
function go(id,onNavigate){const navigate=()=>{dirty=false;close();onNavigate?.();state.viewState='正常';if(route===id)render();else location.hash='/'+id};if(dirty)confirm('离开未保存的编辑？','未保存的正文修改将丢失；已保存的会话草稿和向导步骤会保留。',navigate,'放弃修改并离开');else navigate()}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();notice('导出文件已就绪','PG25','本地文件已生成，可按需重新导出。');setTimeout(()=>URL.revokeObjectURL(url),1000);log('导出合成数据',name);toast('已生成本地文件，导出行为已记录。')}
function csv(name,rows){const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';download(name,'\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function newTask(type,question){createSession(question,type,type!=='简单问答');if(type==='简单问答'){const s=current();s.state='DONE';s.stage='Completed';s.step=4;s.messages.push({role:'assistant',text:'数据缺口指当前来源、时间或字段未覆盖的部分。应单独披露缺口，不把“未查询到”解释为“事实不存在”。此为说明性回答，未调用外部工具。'})}if(current()){current().sourceIds=[...(state.sourceIds||[])];current().contextMode=state.contextMode||'保留当前任务上下文'}go('PG05');commit()}
function ensureBusiness(){if(!state.loggedIn||!state.permission||state.org!=='演示研判一组'||['平台管理员','安全审计人员'].includes(state.role))throw Error('当前身份无权执行业务操作，请重新核验组织和角色。')}
function resume(s){ensureBusiness();if(!s)throw Error('任务不存在');if(!state.network)throw Error('网络未恢复，请先同步快照。');if(s.org!==state.org)throw Error('组织不匹配');if(s.stage==='Terminated')throw Error('已终止任务不可复活。请保留产物并新建任务。');if((s.stage==='Permission'||s.requiresPermission||s.blockedStage==='Permission')&&!s.authorized)throw Error('授权尚未批准，请先完成访问申请。');if(state.files.some(f=>f.session===s.id&&f.invalid))throw Error('当前任务来源已失效，需要重新核验或重新规划。');s.events.filter(e=>['PAUSED','WAITING_APPROVAL'].includes(e.status)).forEach(e=>e.status='RUNNING');startRun(s);commit('已重验上下文，从检查点恢复；已完成动作不重放。')}
function saveWizard(form){if(!form)return;const f=new FormData(form),w=state.wizard;if(w.step===1)Object.assign(w,Object.fromEntries(f));if(w.step===2)w.entities=f.getAll('entities');if(w.step===3)w.tools=f.getAll('tools');w.step=Number(w.step);persist()}
function toolModal(t){state.selectedTool=t.id;formModal('工具契约 · '+t.name,field('显示名称','name',t.name,'text','required')+area('JSON Schema','schema',t.schema,'required rows="7" class="mono"')+field('凭据引用（禁止真实密钥）','credential',t.credential,'text','required pattern="secret://.+"')+field('超时秒数','timeout',t.timeout,'number','required min="5" max="300"')+field('权限声明','permission',t.permission,'text','required')+select('提交操作','operation',['保存草稿','检查本地契约','发布新版本'],'保存草稿')+note('检查只验证本地契约，不验证外部服务连通。编辑后需重新检查再发布。'),f=>{const values={name:f.get('name'),schema:f.get('schema'),credential:f.get('credential'),timeout:Number(f.get('timeout')),permission:f.get('permission')};let schema;try{schema=JSON.parse(values.schema)}catch{throw Error('Schema必须是合法JSON。')}if(schema.type!=='object'||!schema.properties||!Array.isArray(schema.required)||schema.required.some(k=>!schema.properties[k]))throw Error('Schema需包含object类型、properties与有效required字段。');if(!values.credential.startsWith('secret://'))throw Error('仅接受secret://引用。');const same=Object.keys(values).every(k=>values[k]===t[k]);const op=f.get('operation');if(op==='发布新版本'&&(!same||!t.tested))throw Error('请先保存并检查这份完全相同的契约，再发布。');if(op==='发布新版本'){t.history.push({...t,history:[],time:now()});t.version++;t.status='已发布'}else{Object.assign(t,values);t.tested=op==='检查本地契约';t.status='草稿'}log(op,t.id);commit(op==='检查本地契约'?'本地契约检查通过；可再次打开并发布。':op+'完成')})}
