function relationModal(r){formModal(r?'关系详情与人工修订':'新增人工关系',select('起点实体','from',state.entities.map(e=>e.id),r?.from||'E-001')+select('终点实体','to',state.entities.map(e=>e.id),r?.to||'E-002')+field('关系名称','type',r?.type||'人工关联','text','required')+area('依据与修改原因','reason',r?.reason||'','required')+note('来源事实不会被覆盖。修改来源关系时另存为人工补充，保留原始关系。'),f=>{if(f.get('from')===f.get('to'))throw Error('起点终点不能相同');state.graphHistory.push(structuredClone(state.relations));const v={...Object.fromEntries(f),source:'人工补充',version:++state.graphVersion};if(r?.source==='人工补充')Object.assign(r,v);else state.relations.push({id:uid('R'),...v});log('保存人工关系','图谱v'+state.graphVersion);commit('人工关系已保存，原始来源事实未覆盖。')})}
function generateReport(type){ensureBusiness();const s=current(),r={id:uid('REP'),title:type+'研判报告（合成示例）',version:1,status:'草稿',author:state.user,caseId:state.caseId,session:s?.id||'专项合成数据',content:`一、研判目标\n${s?.question||'核验当前合成资料'}\n\n二、范围与来源\n${s?.scope||'近30天，已授权合成来源'}\n\n三、来源事实\n${type==='资金流'?'有效流出3笔，共20000 CNY；冲正2000 CNY单列。':type==='警情问答'?'演示统计82+62+40=184条，仅演示固定口径。':'合成来源中存在2条活动记录，主体与时空冲突需人工复核。'}\n\n四、待核验推断\n关联模式仅为待核验线索，不作确定性定性。\n\n五、数据缺口与限制\n${s?.stage==='PartialSuccess'?'部分来源未完成，结论不覆盖缺失部分。':'仅使用原型合成资料，不连接真实业务系统。'}\n来源引用：[证据01]。未经人工复核。`,history:[],feedback:'',sourceIds:state.files.filter(f=>f.org===state.org&&f.status==='Ready').map(f=>f.id)};state.reports.unshift(r);state.selectedReport=r.id;state.checks={};go('PG24');commit('已生成新报告草稿，原报告保留。')}
function reviewReport(pass){const r=report();if(state.role!=='业务负责人'||r.author===state.user)throw Error('需由不同的业务负责人复核，不允许自审。');if(r.status!=='待复核'||r.reviewVersion!==r.version)throw Error('版本已变化，请重新提交复核');if(pass&&state.files.some(f=>(r.sourceIds||['OBJ-001']).includes(f.id)&&f.invalid))throw Error('存在失效来源，请先重新核验');formModal(pass?'通过当前报告版本':'退回修改',area('复核意见','reason','','required'),f=>{r.status=pass?'已复核':'退回修改';r.feedback=f.get('reason');r.reviewer=state.user;log(pass?'报告复核通过':'报告退回修改',r.id+' v'+r.version);commit('复核结果已绑定v'+r.version)})}
const forms={
 'modal-form':async f=>{const callback=modalCallback;if(!callback)return;await callback(f);close()},
 'composer-form':f=>{ensureBusiness();if(route!=='PG04'&&busy(current()))throw Error('当前执行未结束，请等待或停止确认后再发送。');const q=f.get('prompt').trim();if(!q)throw Error('请输入一个研判问题。');if(q.length>2000)throw Error('问题不能超过2000字');const type=/什么是|如何理解/.test(q)?'简单问答':/交易|账户|资金/.test(q)?'资金流':/警情|统计/.test(q)?'警情问答':'人员流';if(route==='PG04')state.newDraft='';else if(current())current().draft='';if(route!=='PG04'&&current()){const s=current();s.previousRuns||=[];s.previousRuns.push({taskId:s.taskId||s.id+'-T1',events:structuredClone(s.events),step:s.step,state:s.state,stage:s.stage,question:s.question});s.parentTaskId=s.taskId||s.id+'-T1';s.taskId=uid('TASK');s.messages.push({role:'user',text:q});s.question=q;s.sourceIds=[...(state.sourceIds||[])];s.contextMode=state.contextMode||'保留当前任务上下文';s.type=type;s.state='OPEN';s.stage='Clarification';s.step=0;s.events=[];s.planVersion++;s.attempt=1;s.retried=false;s.authorized=false;s.steps=stepsFor(type);go('PG05');commit('已在同一会话追加追问，重新确认范围；历史执行保留。')}else newTask(type,q)},
 'clarify-form':f=>{if(f.get('start')>f.get('end'))throw Error('开始日期不能晚于结束日期。');const s=current();s.type=f.get('type');s.steps=stepsFor(s.type);s.target=f.get('target');s.scope=f.get('target')+' · '+f.get('start')+'至'+f.get('end')+' · '+f.get('source');s.requiresPermission=f.get('source')==='需要扩展授权';s.stage='Planning';s.messages.push({role:'assistant',text:'已确认主体标识与范围，生成待确认计划。确认前不会访问任何来源。'});commit('范围已保存，请确认计划。')},
 'demo-form':f=>{state.scenario=f.get('scenario');state.network=f.has('network');state.auto=f.has('auto');close();commit('演示分支已更新。')},
 'overview-filter':f=>{if(f.get('start')>f.get('end'))throw Error('日期范围无效');state.filters=Object.fromEntries(f);commit('筛选范围已保存用于钻取；当前图表仍是固定合成样本，不是按日期或地域实时查询。')},'history-filter':f=>{state.historyFilter=f.get('query');state.historyStatus=f.get('status');state.historyStart=f.get('start');state.historyCase=f.get('caseId');state.historyPage=1;commit()},
 'fund-filter':f=>{state.fundCurrency=f.get('currency');state.fundStatus=f.get('status');state.fundAccount=f.get('account');commit('已按账户、币种和状态筛选合成明细。')},
 'sql-form':f=>{ensureBusiness();if(f.get('start')>f.get('end'))throw Error('日期范围无效');const sql=f.get('sql').trim();if(!/^select\s/i.test(sql)||/;|--|\/\*|\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|union|join|into|sleep)\b/i.test(sql))throw Error('仅允许单条只读SELECT，不支持写语句、注释、多语句或跨表操作。');if(!/\bfrom\s+demo_alerts\b/i.test(sql)||!/^SELECT category, COUNT\(DISTINCT alert_id\) AS total FROM demo_alerts WHERE occurred_at >= :start AND occurred_at < :end GROUP BY category LIMIT 100$/i.test(sql.replace(/\s+/g,' ')))throw Error('原型只支持页面展示的固定聚合模板；未知字段或其他SQL不能伪造执行结果。请点击“生成演示SQL”。');state.sql=sql;state.dbQuestion=f.get('question');state.sqlExecuted=true;state.sqlRange={start:f.get('start'),end:f.get('end')};log('本地只读SQL检查','demo_alerts');commit('检查通过，显示固定合成结果（非真实数据库查询）。')},
 'case-filter':f=>{state.caseFilter=f.get('query');commit()},'event-filter':f=>{state.eventFilter=f.get('query');state.eventStatus=f.get('status');commit()},
 'wizard-form':(f,form)=>{saveWizard(form);const w=state.wizard;if(w.step===1){if(!w.name.trim())throw Error('请填写研判名称');if(w.registered==='是'&&(!w.caseId||w.caseId==='请选择'))throw Error('已立案任务必须关联一个已授权案件。')}if(w.step===2&&(w.entities.length<1||w.entities.length>5))throw Error('请选择1至5个初始实体。');if(w.step<3){w.step++;commit();return}if(!w.tools.length)throw Error('请至少选择一个已发布工具。');const e={id:uid('EVENT'),name:w.name,type:w.type,caseId:w.registered==='是'?w.caseId:null,business:'待研判',execution:'未开始',updated:now(),entities:[...w.entities],tools:[...w.tools],notes:[],batches:[]};state.events.unshift(e);state.selectedEvent=e.id;log('创建因事研判任务',e.id);dirty=false;go('PG16');commit('任务创建成功；尚未执行工具。')},
 'serial-filter':f=>{state.serial.rule=f.get('rule');state.serial.status='待核验';state.serial.reviewed=false;commit('已按所选规则生成合成候选，需人工核验。')},'file-filter':f=>{state.fileFilter=f.get('query');state.fileArchived=f.has('archived');commit()},
 'upload-form':async f=>{ensureBusiness();const upload=f.get('file');if(!upload?.size)throw Error('文件为空，请选择有内容的合成材料');if(upload.size>2*1024*1024)throw Error('文件超过2MB上限');const ext=upload.name.split('.').pop().toLowerCase();if(!['txt','csv','json'].includes(ext))throw Error('不支持该格式，仅限TXT/CSV/JSON');const content=await upload.text();const obj={id:uid('OBJ'),name:upload.name,type:ext.toUpperCase(),size:(upload.size/1024).toFixed(1)+' KB',status:'Processing',version:1,source:'本地上传的合成材料',session:current()?.id||'未关联',org:state.org,raw:true,archived:false,content};state.files.push(obj);close();commit('文件已接收，等待本地解析。');setTimeout(()=>{try{if(ext==='json')JSON.parse(content);if(content.includes('\u0000'))throw Error('检测到二进制内容');obj.status='Ready';notice('上传材料解析完成','PG19')}catch(e){obj.status='Error';obj.error='解析失败：'+e.message}log('本地文件解析',obj.id,obj.status);commit(obj.status==='Ready'?'文件已就绪，可以预览与引用。':obj.error)},500)},
 'report-form':f=>{ensureBusiness();const r=report();r.history.push({version:r.version,title:r.title,content:r.content,time:now(),status:r.status});r.title=f.get('title').trim();r.content=f.get('content');r.version++;r.status='草稿';r.reviewVersion=null;state.checks={};log('保存报告版本',r.id+' v'+r.version);commit('已生成新版本，旧复核不覆盖新正文。')},
 'export-report-form':f=>{ensureBusiness();if(state.files.some(x=>(report().sourceIds||['OBJ-001']).includes(x.id)&&x.invalid))throw Error('来源引用已失效，请重新核验后再导出。');const r=report();const payload={title:r.title,version:r.version,status:r.status,content:r.content,purpose:f.get('purpose'),sourceIds:r.sourceIds||['OBJ-001'],...(r.caseSources?{caseSources:r.caseSources,graphSnapshot:r.graphSnapshot}:{}),disclaimer:'仅为交互原型合成数据，不作为真实业务结论。'+(r.status==='已复核'?'已模拟人工复核。':'未经人工复核。')};f.get('format').startsWith('JSON')?download(r.title+'.json',JSON.stringify(payload,null,2),'application/json'):download(r.title+'.txt',`${r.title}\n版本：v${r.version} · ${r.status}\n用途：${f.get('purpose')}\n${payload.disclaimer}\n\n${r.content}`);commit()},
 'config-form':f=>{if(!f.getAll('tools').length)throw Error('至少关联一个已发布工具');Object.assign(state.config,{model:f.get('model'),concurrency:Number(f.get('concurrency')),retries:Number(f.get('retries')),timeout:Number(f.get('timeout')),tools:f.getAll('tools'),tested:true});commit('本地配置检查通过，可以发布新版本。')},'audit-filter':f=>{state.auditFilter=f.get('query');commit()},
 'login-form':f=>{state.identityError=f.get('identityError');if(state.identityError!=='正常'){state.loggedIn=false;commit('模拟身份校验未通过，请将演示身份状态改为正常重试。');return}state.loggedIn=true;log('恢复演示身份快照');go(state.returnRoute||'PG05');state.returnRoute=null;commit('已恢复快照，不重发历史工具动作。')}
};
