document.addEventListener('click',async e=>{if(!e.target.closest('.entity-node')&&document.querySelector('.entity-menu')){Object.values(state.graphUI||{}).forEach(ui=>ui.menu=null);document.querySelectorAll('.entity-menu').forEach(menu=>menu.remove());document.querySelectorAll('.node-more[aria-expanded=true]').forEach(button=>button.setAttribute('aria-expanded','false'));persist();}const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();try{const a=actions[el.dataset.action];if(!state.loggedIn&&!['profile','theme','coverage','coverage-tab','coverage-route','feature-detail','flow-start','close','normal','demo','reset-demo'].includes(el.dataset.action))throw Error('身份已失效，请先恢复演示登录。');if(!a)throw Error('该操作尚未注册：'+el.dataset.action);await a(el)}catch(err){toast(err.message)}return}const a=e.target.closest('a[href^="#/PG"]');if(a){e.preventDefault();go(a.hash.slice(2))}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fn=forms[form.id];if(!fn)return;const error=form.querySelector('.form-error');if(error)error.textContent='';if(!form.reportValidity())return;const submit=form.querySelector('[type=submit]');if(submit?.dataset.busy)return;if(submit){submit.dataset.busy='1';submit.disabled=true}try{await fn(new FormData(form),form)}catch(err){if(error)error.textContent=err.message;else toast(err.message)}finally{if(submit){delete submit.dataset.busy;submit.disabled=form.id==='composer-form'?(!document.querySelector('#prompt')?.value.trim()||(route!=='PG04'&&busy(current()))):false}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='prompt'){if(route==='PG04')state.newDraft=t.value;else if(current())current().draft=t.value;const send=document.querySelector('#composer-form [type=submit]');if(send)send.disabled=!t.value.trim()||(route!=='PG04'&&busy(current()));persist()}if(t.id==='side-search'){document.querySelectorAll('.session-tile').forEach(x=>x.hidden=!x.textContent.includes(t.value))}if(t.closest('#report-form,#config-form,#case-material-form'))dirty=true;if(t.closest('#wizard-form')){saveWizard(t.closest('form'));dirty=false}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='view-state'){state.viewState=t.value;commit()}if(t.name==='registered'){document.querySelector('#case-field').hidden=t.value!=='是';saveWizard(t.closest('form'))}if(t.name?.startsWith('report-check-')){state.checks[t.name]=t.checked;persist()}if(t.name==='pref-save'||t.name==='pref-compact'){state.preferences[t.name==='pref-save'?'save':'compact']=t.checked;commit()}});
document.addEventListener('compositionstart',()=>composing=true);document.addEventListener('compositionend',()=>composing=false);
document.addEventListener('keydown',e=>{if(e.target.id==='prompt'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!composing&&e.keyCode!==229){e.preventDefault();document.querySelector('#composer-form')?.requestSubmit()}if(e.key==='Escape'&&overlay.children.length)close();if(e.key==='Tab'&&overlay.children.length){const nodes=[...overlay.querySelectorAll('button:not(:disabled),input:not(:disabled),select,textarea,a[href]')].filter(x=>x.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(['Enter',' '].includes(e.key)&&e.target.matches('svg [role=button]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
